mapper.select:
/* 검사 수치 목록 조회(정렬순서·등록순), 직접입력 항목은 항목명 없음 */ SELECT V.INSP_NVL_SN , V.CKUP_RCD_SN , V.INSP_ARTCL_CD , CASE WHEN V.INSP_ARTCL_DRCT_INPT_NM = '' THEN A.COM_CD_NM END AS INSP_ARTCL_CD_NM , NULLIF(V.INSP_ARTCL_DRCT_INPT_NM, '') AS INSP_ARTCL_DRCT_INPT_NM , V.RSLT_NVL , V.UNIT_NM , V.REF_LLMT_NVL , V.REF_UPLMT_NVL , V.MEMO_CN , V.SORT_SEQ FROM INSP_NVL V LEFT JOIN COM_CD A ON A.COM_CD = V.INSP_ARTCL_CD AND A.COM_CD_PRNT_SN IS NOT NULL WHERE V.CKUP_RCD_SN = #{cond.ckupRcdSn} AND V.DEL_YN = 'N'
AND V.INSP_ARTCL_CD = #{cond.inspArtclCd}
ORDER BY V.SORT_SEQ , V.INSP_NVL_SN

/* 검사 수치별 검진기록 번호 */
SELECT CKUP_RCD_SN
  FROM INSP_NVL
 WHERE DEL_YN = 'N'
   AND INSP_NVL_SN IN

       #{inspNvlSn}

mapper.update:
/* 검사 수치 선택 삭제 */
UPDATE INSP_NVL
   SET DEL_YN   = 'Y'
     , MDFR_ID  = #{actorId}
     , MDFCN_DT = NOW()
 WHERE DEL_YN = 'N'
   AND INSP_NVL_SN IN

       #{inspNvlSn}
